const readSignerRecipientV1 = `-- name: ReadSignerRecipientV1 :one
SELECT r.id, r.document_id, r.role, r.email, r.name, r.order_index, r.status, r.magic_token_hash, r.sent_at, r.first_viewed_at, r.signed_at, r.declined_reason, r.created_at, r.magic_token_expires_at, r.locale,d.org_id AS doc_org_id,d.status AS doc_status FROM recipients r JOIN documents d ON d.id=r.document_id
WHERE r.id=$1::uuid AND r.document_id=$2::uuid AND d.org_id=$3::uuid
 AND d.deleted_at IS NULL AND octet_length($4::bytea)=32
 AND (CASE WHEN octet_length(r.magic_token_hash)=32 THEN r.magic_token_hash ELSE NULL::bytea END)=$4::bytea
 AND (octet_length(r.role)::numeric+octet_length(r.email)+octet_length(r.name)+octet_length(r.status)
  +COALESCE(octet_length(r.declined_reason),0)+octet_length(r.locale)+COALESCE(octet_length(r.magic_token_hash),0)+octet_length(d.status))::bigint=$5::bigint
`

